/** Used for strongly-referenced keys. */
private static class StrongEntry<K, V> extends AbstractReferenceEntry<K, V> {
  final K key;

  StrongEntry(K key, int hash, @Nullable ReferenceEntry<K, V> next) {
    this.key = key;
    this.hash = hash;
    this.next = next;
  }

  @Override
  public K getKey() {
    return this.key;
  }

  // The code below is exactly the same for each entry type.

  final int hash;
  final @Nullable ReferenceEntry<K, V> next;
  volatile ValueReference<K, V> valueReference = unset();

  @Override
  public ValueReference<K, V> getValueReference() {
    return valueReference;
  }

  @Override
  public void setValueReference(ValueReference<K, V> valueReference) {
    this.valueReference = valueReference;
  }

  @Override
  public int getHash() {
    return hash;
  }

  @Override
  public @Nullable ReferenceEntry<K, V> getNext() {
    return next;
  }
}

private static final class StrongAccessEntry<K, V> extends StrongEntry<K, V> {
  StrongAccessEntry(K key, int hash, @Nullable ReferenceEntry<K, V> next) {
    super(key, hash, next);
  }

  // The code below is exactly the same for each access entry type.

  volatile long accessTime = Long.MAX_VALUE;

  @Override
  public long getAccessTime() {
    return accessTime;
  }

  @Override
  public void setAccessTime(long time) {
    this.accessTime = time;
  }

  // Guarded By Segment.this
  @Weak ReferenceEntry<K, V> nextAccess = nullEntry();

  @Override
  public ReferenceEntry<K, V> getNextInAccessQueue() {
    return nextAccess;
  }

  @Override
  public void setNextInAccessQueue(ReferenceEntry<K, V> next) {
    this.nextAccess = next;
  }

  // Guarded By Segment.this
  @Weak ReferenceEntry<K, V> previousAccess = nullEntry();

  @Override
  public ReferenceEntry<K, V> getPreviousInAccessQueue() {
    return previousAccess;
  }

  @Override
  public void setPreviousInAccessQueue(ReferenceEntry<K, V> previous) {
    this.previousAccess = previous;
  }
}

private static final class StrongWriteEntry<K, V> extends StrongEntry<K, V> {
  StrongWriteEntry(K key, int hash, @Nullable ReferenceEntry<K, V> next) {
