  @SuppressWarnings("unchecked") // The natural-ordered empty set supports all types.
  public static <E> ImmutableSortedSet<E> of() {
    return (ImmutableSortedSet<E>) RegularImmutableSortedSet.NATURAL_EMPTY_SET;
  }

